// Differential known answers from the plain-bitassets fork's own code (v0.17.1, built locally): random
// transactions through FilledTransaction::{filled_outputs, bitcoin_fee} and Body::compute_merkle_root, AMM
// PoolState arithmetic (mint, burn, both swaps) and DutchAuctionState::bid, generated by the oracle in
// tools/oracle (tests/data/oracle/*.jsonl). Every result must be identical: bytes, error text, or a panic
// (which we reject as their node cannot connect such a block).
#include "test.h"

#include <bitassets/json.h>
#include <bitassets/state.h>

#include <univalue.h>

#include <cstdio>
#include <filesystem>
#include <fstream>
#include <sstream>

using namespace bitassets;

namespace {

FilledTransaction decode_case(const Bytes& b, Transaction& tx)
{
    Reader r(b);
    tx = de_transaction(r);
    FilledTransaction ft{&tx, {}};
    uint64_t n = r.u64();
    for (uint64_t i = 0; i < n; i++) ft.spent_utxos.push_back(de_filled_output(r));
    if (!r.empty()) throw bt::DecodeError("trailing bytes in case");
    return ft;
}

PoolState pool_from(const UniValue& j)
{
    PoolState p;
    p.reserve0 = j["reserve0"].getInt<uint64_t>();
    p.reserve1 = j["reserve1"].getInt<uint64_t>();
    p.outstanding_lp_tokens = j["outstanding_lp_tokens"].getInt<uint64_t>();
    p.creation_txid = *bt::hex_to_array<32>(j["creation_txid"].get_str());
    return p;
}

template <class F>
std::string pool_result(F f)
{
    try {
        std::string err;
        auto r = f(err);
        if (!r) return "err: " + err;
        return json::pool_state(*r).write();
    } catch (const StateError& e) {
        return e.panic ? "panic" : std::string("throw: ") + e.what();
    }
}

std::string canonical(const UniValue& v)
{
    // sorted keys (serde_json without preserve_order sorts object keys)
    if (v.isObject()) {
        std::vector<size_t> idx(v.size());
        for (size_t i = 0; i < idx.size(); i++) idx[i] = i;
        std::sort(idx.begin(), idx.end(), [&](size_t a, size_t b) { return v.getKeys()[a] < v.getKeys()[b]; });
        std::string o = "{";
        for (size_t k = 0; k < idx.size(); k++) o += (k ? "," : "") + UniValue(v.getKeys()[idx[k]]).write() + ":" + canonical(v.getValues()[idx[k]]);
        return o + "}";
    }
    if (v.isArray()) {
        std::string o = "[";
        for (size_t i = 0; i < v.size(); i++) o += (i ? "," : "") + canonical(v[i]);
        return o + "]";
    }
    return v.write();
}

template <class T>
TxHistory<T> hist_from(const UniValue& a)
{
    TxHistory<T> h;
    for (auto& e : a.getValues()) h.v.push_back({T(e["data"].getInt<uint64_t>()), *bt::hex_to_array<32>(e["txid"].get_str()), uint32_t(e["height"].getInt<uint64_t>())});
    return h;
}

AuctionState auction_from(const UniValue& j)
{
    AuctionState a;
    a.start_block = uint32_t(j["start_block"].getInt<uint64_t>());
    a.most_recent_bid_block = hist_from<uint32_t>(j["most_recent_bid_block"]);
    a.duration = uint32_t(j["duration"].getInt<uint64_t>());
    a.base_asset = json::parse_asset_id(j["base_asset"]);
    a.initial_base_amount = j["initial_base_amount"].getInt<uint64_t>();
    a.base_amount_remaining = hist_from<uint64_t>(j["base_amount_remaining"]);
    a.quote_asset = json::parse_asset_id(j["quote_asset"]);
    a.quote_amount = hist_from<uint64_t>(j["quote_amount"]);
    a.initial_price = j["initial_price"].getInt<uint64_t>();
    a.price_after_most_recent_bid = hist_from<uint64_t>(j["price_after_most_recent_bid"]);
    a.initial_end_price = j["initial_end_price"].getInt<uint64_t>();
    a.end_price_after_most_recent_bid = hist_from<uint64_t>(j["end_price_after_most_recent_bid"]);
    return a;
}

} // namespace

TEST(oracle_fill_fee_merkle_amm_auction)
{
    std::string dir = bttest::data_dir() + "/oracle";
    if (!std::filesystem::exists(dir)) {
        std::fprintf(stderr, "  no oracle data in %s\n", dir.c_str());
        return;
    }
    size_t txs = 0, amm = 0, bids = 0, bad = 0, panics = 0, filled = 0;
    for (auto& f : std::filesystem::directory_iterator(dir)) {
        std::ifstream in(f.path());
        std::string line;
        while (std::getline(in, line)) {
            UniValue j;
            if (!j.read(line)) continue;
            const std::string kind = j["kind"].get_str();
            if (kind == "tx") {
                txs++;
                Transaction tx;
                FilledTransaction ft = decode_case(*bt::hex_decode(j["case"].get_str()), tx);
                // filled_outputs
                std::string got;
                auto fo = ft.filled_outputs();
                if (fo) {
                    Writer w;
                    w.u64(fo->size());
                    for (auto& o : *fo) bincode(w, o);
                    got = bt::hex_encode(w.buf);
                    filled++;
                }
                std::string want = j["filled"].isNull() ? "" : j["filled"].get_str();
                if (got != want) {
                    if (bad++ < 10) std::fprintf(stderr, "  filled_outputs differ: %s\n    theirs %s\n    ours   %s\n", line.substr(0, 300).c_str(), want.c_str(), got.c_str());
                }
                auto fee = ft.bitcoin_fee();
                if (fee != (j["fee"].isNull() ? std::nullopt : std::optional<uint64_t>(j["fee"].getInt<uint64_t>()))) {
                    if (bad++ < 10) std::fprintf(stderr, "  fee differs: %s\n", line.substr(0, 300).c_str());
                }
                auto root = compute_merkle_root(Coinbase{}, std::vector<FilledTransaction>{ft});
                std::string groot = root ? bt::hex_encode(*root) : "", wroot = j["root"].isNull() ? "" : j["root"].get_str();
                if (groot != wroot) {
                    if (bad++ < 10) std::fprintf(stderr, "  merkle root differs: %s\n    theirs %s ours %s\n", line.substr(0, 300).c_str(), wroot.c_str(), groot.c_str());
                }
            } else if (kind == "amm") {
                amm++;
                PoolState p = pool_from(j["pool"]);
                uint64_t a = j["a"].getInt<uint64_t>(), b = j["b"].getInt<uint64_t>();
                std::pair<const char*, std::string> res[] = {
                    {"mint", pool_result([&](std::string& e) { return p.mint(a, b, e); })},
                    {"burn", pool_result([&](std::string& e) { return p.burn(a, e); })},
                    {"s01", pool_result([&](std::string& e) { return p.swap_asset0_for_asset1(a, e); })},
                    {"s10", pool_result([&](std::string& e) { return p.swap_asset1_for_asset0(a, e); })},
                };
                for (auto& [k, ours] : res) {
                    const UniValue& w = j[k];
                    std::string want = w.isStr() ? w.get_str() : canonical(w);
                    std::string mine = ours.rfind("err: ", 0) == 0 || ours == "panic" ? ours : canonical([&] {
                        UniValue x;
                        x.read(ours);
                        return x;
                    }());
                    if (want == "panic") panics++;
                    if (want != mine && bad++ < 20) std::fprintf(stderr, "  AMM %s differs: pool %s a=%llu b=%llu\n    theirs %s\n    ours   %s\n", k, canonical(j["pool"]).c_str(),
                                                                 (unsigned long long)a, (unsigned long long)b, want.c_str(), mine.c_str());
                }
            } else if (kind == "bid") {
                bids++;
                AuctionState st = auction_from(j["state"]);
                Hash32 txid;
                txid = *bt::hex_to_array<32>("0707070707070707070707070707070707070707070707070707070707070707");
                std::string mine;
                try {
                    std::string err;
                    auto r = st.bid(txid, j["bid"].getInt<uint64_t>(), uint32_t(j["height"].getInt<uint64_t>()), err);
                    mine = r ? canonical(json::auction_state(*r)) : "err: " + err;
                } catch (const StateError& e) {
                    mine = e.panic ? "panic" : std::string("throw: ") + e.what();
                }
                const UniValue& w = j["result"];
                std::string want = w.isStr() ? w.get_str() : canonical(w);
                if (want == "panic") panics++;
                if (want != mine && bad++ < 30) std::fprintf(stderr, "  bid differs: %s\n    theirs %s\n    ours   %s\n", line.substr(0, 400).c_str(), want.c_str(), mine.c_str());
            }
        }
    }
    std::fprintf(stderr, "  %zu tx cases (%zu fill), %zu AMM cases, %zu auction bids, %zu panics in theirs reproduced; %zu differences\n", txs, filled, amm, bids, panics,
                 bad);
    CHECK_EQ(bad, size_t(0));
}
